-- Lot 2 : synchronisation des 10543 liens P_DoublonPropertyId (10530 doublons lies sur 6464 groupes, 13 anciens liens purges).
-- Audit lecture seule du 2026-11-22 : 47670 actifs (hors P_EstRattrapage = 4), hit.properties[] (source=AD, meme P_TypeTransaction).
-- A executer UNIQUEMENT sur ordre ecrit explicite de l utilisateur.
-- Ne ferme aucun bien (P_State, P_DateFin, P_EstRattrapage et P_DateLastUpdate inchanges).
-- Retour arriere : infra/ovh/sql/20261122-yanport-doublons-link-rollback.sql

-- Test a blanc (SELECT uniquement, avant ecriture) :
-- SELECT COUNT(*) AS actifs_avec_doublon_avant FROM property WHERE P_State = 1 AND (P_DateFin IS NULL OR P_DateFin < '1000-01-01') AND P_DoublonPropertyId IS NOT NULL AND P_DoublonPropertyId <> '';

CREATE TABLE IF NOT EXISTS backup_property_20261122_yanport_doublons (
  P_PropertyId VARCHAR(40) NOT NULL PRIMARY KEY,
  new_doublon_id VARCHAR(40) NULL,
  old_doublon_id VARCHAR(40) NULL,
  captured TINYINT NOT NULL DEFAULT 0,
  captured_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

START TRANSACTION;























-- Capture de l etat exact avant modification pour un retour arriere 1:1.
UPDATE backup_property_20261122_yanport_doublons b
INNER JOIN property p ON p.P_PropertyId = b.P_PropertyId
SET b.old_doublon_id = p.P_DoublonPropertyId,
    b.captured = 1
WHERE b.captured = 0
  AND p.P_State = 1
  AND (p.P_DateFin IS NULL OR p.P_DateFin < '1000-01-01')
  AND IFNULL(p.P_EstRattrapage, 0) <> 4;

SELECT SUM(new_doublon_id IS NOT NULL) AS to_link, SUM(new_doublon_id IS NULL) AS to_clear
FROM backup_property_20261122_yanport_doublons
WHERE captured = 1;

-- Mise a jour securisee (idempotente, ne touche pas P_State / P_DateFin / P_DateLastUpdate).
UPDATE property p
INNER JOIN backup_property_20261122_yanport_doublons b ON b.P_PropertyId = p.P_PropertyId
SET p.P_DoublonPropertyId = b.new_doublon_id
WHERE b.captured = 1
  AND p.P_State = 1
  AND (p.P_DateFin IS NULL OR p.P_DateFin < '1000-01-01')
  AND IFNULL(p.P_EstRattrapage, 0) <> 4;

SELECT ROW_COUNT() AS updated_rows;

SELECT COUNT(*) AS actifs_avec_doublon_apres, COUNT(DISTINCT P_DoublonPropertyId) AS groupes_actifs
FROM property
WHERE P_State = 1
  AND (P_DateFin IS NULL OR P_DateFin < '1000-01-01')
  AND P_DoublonPropertyId IS NOT NULL
  AND P_DoublonPropertyId <> '';

COMMIT;
